#include <iostream>
#include <vector>
#include <list>
#include <algorithm>
#include <iterator>

int main() {
    std::vector<int> src = {1, 2, 3, 4, 5, 6, 7, 8, 9};  // Source vector from 1 to 9
    std::list<int> dest;  // Empty list for front insertion

    // Copy using front_inserter: Inserts at the beginning, reversing the order
    std::copy(src.cbegin(), src.cend(), std::front_inserter(dest));

    // Output the result
    std::cout << "Elements in dest (front_inserter): ";
    for (const auto& elem : dest) {
        std::cout << elem << " ";  // Should print in reverse: 9 8 7 6 5 4 3 2 1
    }
    std::cout << std::endl;
    return 0;
}
